48	func eventOf(t *testing.T, r map[string]any) map[string]any {
49		t.Helper()
50		event, ok := r["event"].(map[string]any)
51		if !ok {
52			t.Fatalf("result has no event: %#v", r)
53		}
54		return event
55	}
