746	// mustNumber asserts v is a JSON number whose serialized form is exactly
747	// want — no rounding, no truncation, no conversion to string.
748	func mustNumber(t *testing.T, v any, want string) {
749		t.Helper()
750		n, ok := v.(json.Number)
751		if !ok {
752			t.Fatalf("expected JSON number %s, got %T (%v)", want, v, v)
753		}
754		if n.String() != want {
755			t.Fatalf("number preserved as %q, want %q", n.String(), want)
756		}
757	}
