341	// White-box pin for the exact trim set: trimJSONWhitespace must remove only
342	// the four RFC 8259 whitespace bytes from the document edges. It must keep
343	// every other whitespace-looking byte so the decoder gets a chance to reject
344	// it, and it must not touch interior bytes at all.
345	func TestTrimJSONWhitespaceSet(t *testing.T) {
346		const doc = `{"a":1}`
347	
348		t.Run("exactly the four JSON whitespace bytes are trimmed", func(t *testing.T) {
349			for _, c := range []byte{' ', '\t', '\r', '\n'} {
350				raw := bytes.Join([][]byte{{c, c}, []byte(doc), {c}}, nil)
351				if got := trimJSONWhitespace(raw); string(got) != doc {
352					t.Fatalf("byte %q must be trimmed from the edges, got %q", c, got)
353				}
354			}
355		})
356	
357		t.Run("all other whitespace-looking bytes survive at the edges", func(t *testing.T) {
358			// Each prefix is one complete non-JSON-whitespace rune (plus one
359			// single-byte control); none of their bytes may be in the trim set.
360			for _, prefix := range []string{
361				"\x0b",             // vertical tab
362				"\x0c",             // form feed
363				string(rune(0x85)), // U+0085 next line
364				noBreakSpace,       // U+00A0
365				ideographicSpace,   // U+3000
366			} {
367				raw := append([]byte(prefix), []byte(doc)...)
368				trimmed := trimJSONWhitespace(raw)
369				if len(trimmed) != len(raw) || !bytes.HasPrefix(trimmed, []byte(prefix)) {
370					t.Fatalf("rune %q must not be trimmed like JSON whitespace, got %q", prefix, trimmed)
371				}
372			}
373		})
